import { describe, it, expect } from "vitest";
import { buildOrgFleetData, buildRealFleetData, fleetToOrg, teamToOrg, nodeHasLiveSession, livePanesForProject, withPreviewNode, PREVIEW_NODE_ID, PLANNER_NODE_ID, resolveSystemSessions, systemSessionLabel } from "@/features/glance/lib/glanceFleet";
import type { FleetPlan } from "@/features/planner/fleet/planFleet";
import type { Persona } from "@/features/personas";
import type { Team } from "@/features/teams";
import type { BlueprintTeam } from "@/features/planner/stages/blueprintTypes";

describe("buildRealFleetData (glance drill — real fleet)", () => {
  const personas: Persona[] = [
    { id: "p-worker", name: "Backend Engineer", blurb: "", role: "worker", startPrompt: "", skills: ["rust", "api"], model: "claude-sonnet-5", responsibilities: ["owns the API"] },
    { id: "p-reviewer", name: "Reviewer", blurb: "", role: "reviewer", startPrompt: "", skills: [] },
  ];
  const fleet = {
    recommended: 2, reasoning: "",
    streams: [
      { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [], persona: "p-worker" },
      { id: "ui", name: "UI", repo: "r", owns: [], issues: [], dependsOn: ["api"], persona: "p-worker" },
      { id: "qa", name: "QA", repo: "r", owns: [], issues: [], dependsOn: [], persona: "p-reviewer" },
    ],
    director: { enabled: true },
    edges: [{ id: "e1", from: "api", to: "ui", kind: "handoff" as const, hardness: "blocking" as const, via: "direct" as const }],
  } as unknown as FleetPlan;

  it("maps streams→nodes (role via persona), a director hub, and coordination + dependsOn edges", () => {
    const d = buildRealFleetData(fleet, personas);
    expect(d.sample).toBe(false);
    const byId = Object.fromEntries(d.rawNodes.map((n) => [n.id, n]));
    expect(byId.api.role).toBe("service");   // worker → service (colour category)
    expect(byId.api.roleLabel).toBe("worker"); // real role carried for display
    expect(byId.qa.role).toBe("data");       // reviewer → data
    expect(byId.qa.roleLabel).toBe("reviewer");
    expect(byId.director.role).toBe("infra");// director hub added
    expect(byId.director.roleLabel).toBe("director");
    // director hub: each stream is MANAGED by the director (Org archetype #2561)
    expect(d.rawEdges).toContainEqual({ from: "api", to: "director", kind: "api", archetype: "manages" });
    // dependsOn + the handoff both resolve to a single ui→api PEERS edge (deduped)
    expect(d.rawEdges.filter((e) => e.from === "ui" && e.to === "api")).toEqual([{ from: "ui", to: "api", kind: "api", archetype: "peers" }]);
  });

  it("surfaces each stream's persona on its node (#2561): name · model · skills · responsibilities", () => {
    const d = buildRealFleetData(fleet, personas);
    const api = d.rawNodes.find((n) => n.id === "api")!;
    expect(api.persona).toMatchObject({ name: "Backend Engineer", role: "worker", model: "claude-sonnet-5", skills: ["rust", "api"], responsibilities: ["owns the API"] });
    expect(api.persona!.comms!.length).toBeGreaterThan(0); // its communication surface is attached (#2563)
    // a persona with no model/responsibilities resolves to empty arrays, not undefined holes
    const qa = d.rawNodes.find((n) => n.id === "qa")!;
    expect(qa.persona).toMatchObject({ name: "Reviewer", role: "reviewer", skills: [], responsibilities: [] });
  });

  it("tags the coordination edge with its Org archetype (review→oversees, handoff→peers)", () => {
    const withReview = { ...fleet, edges: [{ id: "e2", from: "api", to: "qa", kind: "review", hardness: "blocking", via: "direct" }] } as unknown as FleetPlan;
    const d = buildRealFleetData(withReview, personas);
    // review edge producer(api)→consumer(qa) becomes qa→api, archetype OVERSEES
    expect(d.rawEdges).toContainEqual({ from: "qa", to: "api", kind: "data", archetype: "oversees" });
  });
});

describe("fleetToOrg (#2563 — the fleet-as-Org projection)", () => {
  const fleet = {
    recommended: 2, reasoning: "",
    streams: [
      { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [], persona: "p-worker" },
      { id: "ui", name: "UI", repo: "r", owns: [], issues: [], dependsOn: ["api"], persona: "p-worker" },
    ],
    director: { enabled: true },
    edges: [{ id: "e1", from: "api", to: "ui", kind: "handoff", hardness: "blocking", via: "direct" }],
  } as unknown as FleetPlan;

  it("projects streams (+ director) into positions and coordination into archetype relationships", () => {
    const org = fleetToOrg(fleet);
    expect(org.positions.map((p) => p.nodeId).sort()).toEqual(["api", "director", "ui"]);
    expect(org.positions.find((p) => p.nodeId === "api")).toMatchObject({ kind: "agent", personaId: "p-worker" });
    // the director MANAGES each stream
    expect(org.relationships).toContainEqual(expect.objectContaining({ from: "director", to: "api", archetype: "manages" }));
    expect(org.relationships).toContainEqual(expect.objectContaining({ from: "director", to: "ui", archetype: "manages" }));
    // the handoff + dependsOn between api and ui collapse to ONE peers seam
    expect(org.relationships.filter((r) => r.from === "api" && r.to === "ui")).toEqual([expect.objectContaining({ archetype: "peers" })]);
  });

  it("omits the director position + manages relationships when there is no director", () => {
    const org = fleetToOrg({ ...fleet, director: { enabled: false } });
    expect(org.positions.some((p) => p.nodeId === "director")).toBe(false);
    expect(org.relationships.some((r) => r.archetype === "manages")).toBe(false);
  });

  // ── the planner position ──────────────────────────────────────────────────
  it("has NO planner node — the drill starts at the director", () => {
    // REVERSES #glance-planner-node-per-project on the maintainer's call: the planning session authored
    // the plan but is not part of the RUNTIME picture. Nothing synthesizes it any more.
    const org = fleetToOrg(fleet);
    expect(org.positions.some((p) => p.nodeId === PLANNER_NODE_ID)).toBe(false);
    expect(org.relationships.some((r) => r.from === PLANNER_NODE_ID || r.to === PLANNER_NODE_ID)).toBe(false);
  });

  it("excludes a REAL `planner` stream too, not just the synthesized node", () => {
    // Dropping only the synthetic position would leave studio-code's real stream — named "Project
    // planning session" — sitting in exactly the same place under a different label, which is the node
    // that was asked to go. `planner` is a reserved id that no longer renders, whatever its origin.
    const org = fleetToOrg({
      ...fleet,
      streams: [
        { id: "planner", name: "Project planning session", repo: "r", owns: [], issues: [], dependsOn: [] },
        { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [] },
      ],
    } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === PLANNER_NODE_ID)).toBe(false);
    expect(org.positions.some((p) => p.label === "Project planning session")).toBe(false);
    // every OTHER stream is still managed — the exclusion is scoped to the one id
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "director", to: "api", archetype: "manages" }),
    );
  });

  it("a planner stream's edges vanish with it — the cycle that blanked the graph", () => {
    // Regression, and the reason the exclusion is by ID rather than by "was it synthesized". A real
    // `planner` stream WITH dependsOn sat below the director (director manages console, planner depends
    // on console) and above it (planner serves director), closing
    //   console -> planner -> director -> console
    // `mutualPairs` only finds 2-cycles, so this never reached layerDag's break set: measured at layer
    // 141 across 46 nodes, spreading the graph over 142 columns — an empty canvas. With the planner no
    // longer a position, `rel()` drops these on its posIds guard.
    const org = fleetToOrg({
      ...fleet,
      streams: [
        { id: "planner", name: "Planning", repo: "r", owns: [], issues: [], dependsOn: ["console"] },
        { id: "console", name: "Console", repo: "r", owns: [], issues: [], dependsOn: [] },
      ],
      edges: [{ id: "e9", from: "planner", to: "console", kind: "handoff", hardness: "blocking", via: "direct" }],
    } as unknown as FleetPlan);
    expect(org.relationships.some((r) => r.from === PLANNER_NODE_ID || r.to === PLANNER_NODE_ID)).toBe(false);
    // Everyone else's edges are untouched.
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "director", to: "console", archetype: "manages" }),
    );
  });

  it("keeps a NON-planner dependsOn edge — the skip is scoped, not a blanket drop", () => {
    const org = fleetToOrg({
      ...fleet,
      streams: [
        { id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [] },
        { id: "web", name: "Web", repo: "r", owns: [], issues: [], dependsOn: ["api"] },
      ],
      edges: [],
    } as unknown as FleetPlan);
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "api", to: "web", archetype: "peers" }),
    );
  });

  it("admits an injected `debugger` session and wires it to the director like the rest", () => {
    // The debugger is app-owned but NEVER project-declared: while a request is open the caller injects
    // it into `systemSessions`, so the node appears with the queue and leaves with it. `resolveSystemSessions`
    // filters to KNOWN ids, so this only works because `debugger` is in the roles map — before that it
    // was silently dropped, which reads as "the feature does nothing".
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "debugger"] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === "debugger")).toBe(true);
    expect(org.relationships).toContainEqual(
      expect.objectContaining({ from: "debugger", to: "director", archetype: "serves" }),
    );
    // and it is NOT a worker — the role fallback would colour it as one
    expect(buildOrgFleetData(org, []).rawNodes.find((n) => n.id === "debugger")?.roleLabel).toBe("debugger");
  });

  it("drops the debugger again when nothing injects it — the node is not sticky", () => {
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect"] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === "debugger")).toBe(false);
  });

  it("the system sessions SERVE the director", () => {
    // The maintainer's directive: the sessions wire straight to the director, with no planning node
    // between them. `serves` (not `manages`) keeps the authority chain reading one way, and is what
    // layers them LEFT of the director.
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "integrator"] } as unknown as FleetPlan);
    for (const s of ["architect", "integrator"]) {
      expect(org.relationships).toContainEqual(
        expect.objectContaining({ from: s, to: "director", archetype: "serves" }),
      );
    }
    expect(org.relationships.some((r) => r.to === PLANNER_NODE_ID)).toBe(false);
  });

  it("a director-less fleet still renders, with the sessions simply serving nothing", () => {
    // The old code kept a planner node so the graph never "lost the agent that authored the plan".
    // Now there is no such node, so the no-director case must not leave an orphan in its place.
    const org = fleetToOrg({ ...fleet, director: { enabled: false }, systemSessions: ["architect"] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === PLANNER_NODE_ID)).toBe(false);
    expect(org.positions.some((p) => p.nodeId === "architect")).toBe(true);
    expect(org.relationships.some((r) => r.from === "architect")).toBe(false);
  });

  // ── declared system sessions ──────────────────────────────────────────────
  it("renders ONLY the system sessions the project declares, each serving the director", () => {
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "integrator"] } as unknown as FleetPlan);
    expect(org.positions.map((p) => p.nodeId).sort())
      .toEqual(["api", "architect", "director", "integrator", "ui"]);
    for (const s of ["architect", "integrator"]) {
      expect(org.relationships).toContainEqual(
        expect.objectContaining({ from: s, to: "director", archetype: "serves" }),
      );
    }
    // the ones it did NOT declare are absent — a project with no UI kit shows no designer
    expect(org.positions.some((p) => p.nodeId === "sound-designer")).toBe(false);
    expect(org.positions.some((p) => p.nodeId === "designer-react")).toBe(false);
  });

  it("declares none ⇒ renders none", () => {
    const org = fleetToOrg(fleet);
    for (const s of ["designer", "librarian", "architect", "sound-designer", "integrator"]) {
      expect(org.positions.some((p) => p.nodeId === s)).toBe(false);
    }
  });

  it("ignores an unknown system-session id rather than rendering a phantom agent", () => {
    // A typo should cost that one node, not put an agent on the graph no session can ever back.
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "architetc", ""] } as unknown as FleetPlan);
    expect(org.positions.some((p) => p.nodeId === "architetc")).toBe(false);
    expect(org.positions.some((p) => p.nodeId === "architect")).toBe(true);
    // de-duped, and a MULTI-TECH kind expands to its real sessions rather than the bare kind
    expect(resolveSystemSessions(["architect", "architetc", "architect"])).toEqual(["architect"]);
    expect(resolveSystemSessions(["designer"])).toEqual(["designer-react", "designer-react-native"]);
  });

  it("renders each system session in its own role, not as a worker", () => {
    // A per-technology node keeps its KIND's role — `librarian-rust` is a librarian, not a worker.
    const data = buildOrgFleetData(
      fleetToOrg({ ...fleet, systemSessions: ["librarian"] } as unknown as FleetPlan), [],
    );
    expect(data.rawNodes.find((n) => n.id === "librarian-rust")).toMatchObject({ roleLabel: "librarian", role: "client" });
    expect(data.rawNodes.some((n) => n.id === "librarian")).toBe(false); // the bare kind is never a node
  });

  it("expands a declared kind into ONE NODE PER TECHNOLOGY, labelled", () => {
    // A project declares `designer`, but no such SESSION exists — there is design-studio:designer-react
    // and …-react-native. Rendering the bare kind gives a node that can never open anything, because the
    // pane-id map is keyed per technology. Each variant is its own openable node instead.
    const org = fleetToOrg({ ...fleet, systemSessions: ["designer", "librarian"] } as unknown as FleetPlan);
    const ids = org.positions.map((p) => p.nodeId);
    expect(ids).toEqual(expect.arrayContaining([
      "designer-react", "designer-react-native", "librarian-rust", "librarian-typescript", "librarian-python",
    ]));
    expect(ids).not.toContain("designer");
    expect(ids).not.toContain("librarian");
    // labelled for a human, while the id stays the machine identity
    expect(org.positions.find((p) => p.nodeId === "designer-react")?.label).toBe("designer · react");
    expect(systemSessionLabel("librarian-typescript")).toBe("librarian · typescript");
    expect(systemSessionLabel("architect")).toBe("architect"); // no technologies ⇒ unchanged
    // every variant serves the director, exactly like a single-session kind
    for (const id of ["designer-react", "librarian-python"]) {
      expect(org.relationships).toContainEqual(
        expect.objectContaining({ from: id, to: "director", archetype: "serves" }),
      );
    }
  });

  it("places system sessions LEFT of the director, workers right", () => {
    // The arrangement is a CONSEQUENCE of `serves`, not a layout rule — so assert the layering the real
    // chain produces. Glance inverts org relationships into `from depends on to`, then reverses again
    // for layerDag, so a `serves` edge puts the server at the lower (further-left) layer.
    const org = fleetToOrg({ ...fleet, systemSessions: ["architect", "integrator"] } as unknown as FleetPlan);
    const glance = buildOrgFleetData(org, []).rawEdges;               // already inverted once
    const rev = glance.map((e, i) => ({ id: `e${i}`, from: e.to, to: e.from })); // glanceGraph's reversal
    const ids = org.positions.map((p) => p.nodeId);
    const layer: Record<string, number> = Object.fromEntries(ids.map((i) => [i, 0]));
    for (let k = 0; k <= ids.length; k++) {
      let changed = false;
      for (const e of rev) {
        if (layer[e.to] < layer[e.from] + 1) { layer[e.to] = layer[e.from] + 1; changed = true; }
      }
      if (!changed) break;
    }
    expect(layer.architect).toBeLessThan(layer.director);
    expect(layer.integrator).toBeLessThan(layer.director);
    expect(layer.director).toBeLessThan(layer.api);
    expect(layer.director).toBeLessThan(layer.ui);
  });

  it("renders orchestrating agents in the ORCHESTRATE bucket, not as workers", () => {
    // Without the role fallback knowing the id, an unmatched persona falls through to `worker` and an
    // orchestrating agent would draw in the BUILD colour. The planner node is gone (it is no longer a
    // position at all), so the surviving orchestrators are the director and the system sessions.
    const data = buildOrgFleetData(fleetToOrg({ ...fleet, systemSessions: ["architect"] } as unknown as FleetPlan), []);
    expect(data.rawNodes.find((n) => n.id === "architect")?.roleLabel).toBe("architect"); // NOT the worker fallback
    // the director keeps its own fallback
    expect(data.rawNodes.find((n) => n.id === "director")).toMatchObject({ role: "infra", roleLabel: "director" });
    // a stream with no persona still falls through to worker
    expect(data.rawNodes.find((n) => n.id === "api")?.roleLabel).toBe("worker");
  });
});

describe("buildRealFleetData attaches each agent's communication surface (#2563)", () => {
  const personas: Persona[] = [{ id: "p-worker", name: "Backend Engineer", blurb: "", role: "worker", startPrompt: "", skills: [] }];
  const fleet = {
    recommended: 1, reasoning: "",
    streams: [{ id: "api", name: "API", repo: "r", owns: [], issues: [], dependsOn: [], persona: "p-worker" }],
    director: { enabled: true },
  } as unknown as FleetPlan;

  it("the director's persona lists a Manages relationship to each stream, SENDING a Directive", () => {
    const d = buildRealFleetData(fleet, personas);
    const toApi = d.rawNodes.find((n) => n.id === "director")!.persona!.comms!.find((c) => c.withName === "API");
    expect(toApi).toBeTruthy();
    expect(toApi!.archetypeLabel).toBe("Manages");
    expect(toApi!.sends.map((f) => f.label)).toContain("Directive");
  });

  it("the worker's persona lists the same relationship from its side — RECEIVING the Directive (with its bsc-* transport)", () => {
    const d = buildRealFleetData(fleet, personas);
    const fromDir = d.rawNodes.find((n) => n.id === "api")!.persona!.comms!.find((c) => c.withName === "director");
    expect(fromDir).toBeTruthy();
    const directive = fromDir!.receives.find((f) => f.label === "Directive");
    expect(directive).toBeTruthy();
    expect(directive!.transport).toBe("bsc-assign");
  });
});

